<?php /** One line of a draft as an editable row (the inputs belong to a form rendered after the table: form="line-form-{id}"); or the blank add row. Data: e, l (null = the add row), pdo, departments, sites, taxRates */
$id = (int) $e['journal_entry_id']; $lid = $l === null ? 'new' : (int) $l['journal_line_id']; $f = 'line-form-' . $lid; $rid = 'entry-line-' . $lid;
$ctl = $l !== null && $l['is_control']; $showCustomer = $l === null || ($ctl && $l['subtype'] === 'receivable'); $showVendor = $l === null || ($ctl && $l['subtype'] === 'payable'); ?>
<tr id="<?= $rid ?>" class="<?= $l === null ? 'table-light' : '' ?>">
    <td class="text-muted fs-12 align-middle"><?= $l === null ? '+' : (int) $l['line_no'] ?></td>
    <td><?= account_select($pdo, 'account', $l['account_id'] ?? null, [], [], 'form="' . $f . '" required', $l === null ? '— account —' : null, $rid . '-account') ?></td>
    <td><input form="<?= $f ?>" type="text" name="description" class="form-control form-control-sm" maxlength="300" value="<?= e($l['description'] ?? '') ?>" id="<?= $rid ?>-description"></td>
    <td><input form="<?= $f ?>" type="text" inputmode="decimal" name="debit" class="form-control form-control-sm text-end" value="<?= $l !== null && (float) $l['debit'] > 0 ? e($l['debit']) : '' ?>" id="<?= $rid ?>-debit"></td>
    <td><input form="<?= $f ?>" type="text" inputmode="decimal" name="credit" class="form-control form-control-sm text-end" value="<?= $l !== null && (float) $l['credit'] > 0 ? e($l['credit']) : '' ?>" id="<?= $rid ?>-credit"></td>
    <td><select form="<?= $f ?>" name="department" class="form-select form-select-sm" id="<?= $rid ?>-department"><option value="">—</option><?php foreach ($departments as $d): ?><option value="<?= (int) $d['department_id'] ?>" <?= ($l['department_id'] ?? $e['department_id']) === (int) $d['department_id'] ? 'selected' : '' ?>><?= e($d['name']) ?></option><?php endforeach; ?></select></td>
    <td><select form="<?= $f ?>" name="site" class="form-select form-select-sm" id="<?= $rid ?>-site"><option value="">—</option><?php foreach ($sites as $s): ?><option value="<?= (int) $s['site_id'] ?>" <?= ($l['site_id'] ?? $e['site_id']) === (int) $s['site_id'] ? 'selected' : '' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select></td>
    <td><?php if ($showCustomer): ?><?= party_select($pdo, 'customer', 'customer', $l['customer_id'] ?? null, 'form="' . $f . '"', $l === null ? 'customer…' : 'None', $rid . '-customer') ?><?php endif; ?><?php if ($showVendor): ?><?= party_select($pdo, 'vendor', 'vendor', $l['vendor_id'] ?? null, 'form="' . $f . '"' . ($showCustomer ? ' class="form-select form-select-sm mt-1"' : ''), $l === null ? 'vendor…' : 'None', $rid . '-vendor') ?><?php endif; ?><?php if (!$showCustomer && !$showVendor): ?><span class="text-muted fs-12">—</span><?php endif; ?></td>
    <td><select form="<?= $f ?>" name="tax_rate" class="form-select form-select-sm" id="<?= $rid ?>-tax"><option value="">—</option><?php foreach ($taxRates as $t): ?><option value="<?= $t['tax_rate_id'] ?>" <?= ($l['tax_rate_id'] ?? null) === $t['tax_rate_id'] ? 'selected' : '' ?>><?= e($t['name']) ?></option><?php endforeach; ?></select></td>
    <td class="text-nowrap"><button form="<?= $f ?>" type="submit" class="btn btn-sm btn-primary" id="<?= $rid ?>-save-btn"><?= $l === null ? 'Add' : 'Save' ?></button><?php if ($l !== null): ?> <button form="line-remove-<?= $lid ?>" type="submit" class="btn btn-sm btn-light text-danger" id="<?= $rid ?>-remove-btn" title="Remove">&times;</button><?php endif; ?></td>
</tr>
